/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK computeVoiceGains(s32, s32, M2C_UNK, M2C_UNK, s32, s32, s32, s32); /* extern */
extern s32 gAudioVoiceTable;

/* Computes gains for a voice (0x68-byte table entry), writing results into the voice's gain fields. */ void setVoiceGains(s32 voiceIndex, M2C_UNK pan, M2C_UNK volume, s32 param3, s32 param4) {
    s32 voice;

    voice = gAudioVoiceTable + (voiceIndex * 0x68);
    computeVoiceGains(voice + 0x42, voice + 0x40, pan, volume, param3, voice + 0x44, param4, voice + 0x46);
}
